use std::mem;

fn main() {
    struct Value {
        a: i32,
        b: i32,
    };

    let Value { a, b } = unsafe { mem::zeroed() };
    println!("{} {}", a, b);
}
```

It states that `Value` is never constructed when in fact it has been within the `let Value { a, b }` pattern match.

```
